  stream_track: {
    parameters: {
      query?: {
        /** @description Только для перекодируемых треков: начать с этой секунды (перемотка). */
        t?: number;
        /**
         * @description `1` — полный файл для сохранения на устройстве: `Content-Disposition: attachment`
         *     и увеличенный таймаут простоя (120 с). Остальное поведение — как у обычного стрима.
         */
        download?: number;
      };
      header?: never;
      path: {
        /** @description ID трека */
        id: number;
      };
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Аудио целиком (`audio/*`); для завершённого файла — `ETag`, `Cache-Control: private, no-cache`; с `download=1` — `Content-Disposition: attachment`; для перекодируемых треков — `audio/flac` без Range (`X-Nimbus-Transcode: 1`, `X-Nimbus-Duration-Ms`) */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Часть аудио по заголовку Range (только прямая отдача) */
      206: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Завершённый файл не изменился (`If-None-Match` совпал с `ETag`) */
      304: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Нет такого трека */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description Трек не `found`/`ready` (`track_not_playable`) */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description Диапазон вне файла */
      416: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description CUE-образ ещё докачивается, трек из него пока не играет (`image_downloading`) */
      425: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description Нет ffmpeg (`ffmpeg_missing`) или слишком много перекодирований (`transcoder_busy`) */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description Нет пиров: данные не пришли вовремя (`no_peers`) */
      504: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
      /** @description Ошибка хранилища торрент-движка, например нет места (`storage_error`) */
      507: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['ErrorResponse'];
        };
      };
    };
  };
